import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv.removeprefix("\ufeff"), newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        skipinitialspace=False,
    )

    columns = []
    for record in reader:
        if not record or (len(record) == 1 and not record[0].strip()):
            continue
        if record in (["sep=", ""], ["sep=,"]):
            continue
        columns = record
        break
    else:
        return {"columns": [], "rows": []}

    rows = list(reader)
    width = max(10, len(columns), max(map(len, rows), default=0))

    # Preserve surplus fields rather than guessing where a delimiter belonged.
    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
